def path_crosses_itself(path):
 x=y=0;seen={(0,0)};moves={'N':(0,1),'S':(0,-1),'E':(1,0),'W':(-1,0)}
 for char in path:
  dx,dy=moves[char];x+=dx;y+=dy
  if (x,y) in seen:return True
  seen.add((x,y))
 return False

